import React, { Component } from 'react';

import { Link } from 'react-router-dom';

class JotsList extends Component {
  constructor(props) {
    super(props);

    this.state = {topic: this.props.match.params.topic, links: []};
  }

  componentDidMount() {
    this.setState({
      ...this.state,
      links: [{key: "who", title: "Who is God"}]
    })
  }

  render() {
    let list;

    if (this.state.links.length === 0) {
      list = <p> Hmmm... Not much here now </p>;
    } else {
      list = <ul>
               {this.state.links.map(link => (
                 <li key={link.key.toString}>
                   <Link to={"/jots/" + link.key}>
                     {link.title}
                   </Link>
                 </li>
               ))}
             </ul>;
    }

    return (
      <div className='App-body'>
        <div className='Vertical-list'>
          <h1>jots about {this.state.topic}</h1>
          {list}
        </div>
      </div>
    )
  }
}

export default JotsList;
